func (p productPayload) toMap() map[string]interface{} {
	body := map[string]interface{}{}
	if p.name != nil {
		body["name"] = *p.name
	}
	if p.code != nil {
		body["code"] = *p.code
	}
	if p.description != nil {
		body["description"] = *p.description
	}
	if p.unit != nil {
		body["unit"] = *p.unit
	}
	if p.tax != nil {
		body["tax"] = *p.tax
	}
	if p.category != nil {
		body["category"] = *p.category
	}
	if p.ownerID != nil {
		body["owner_id"] = int(*p.ownerID)
	}
	if p.isLinkable != nil {
		body["is_linkable"] = *p.isLinkable
	}
	if p.visibleTo != nil {
		body["visible_to"] = *p.visibleTo
	}
	if p.prices.set {
		body["prices"] = p.prices.value
	}
	if p.billingFrequency != nil {
		body["billing_frequency"] = *p.billingFrequency
	}
	if p.billingFrequencyCycles.set {
		if p.billingFrequencyCycles.value == nil {
			body["billing_frequency_cycles"] = nil
		} else {
			body["billing_frequency_cycles"] = *p.billingFrequencyCycles.value
		}
	}
	return body
}

func (p productVariationPayload) toMap() map[string]interface{} {
	body := map[string]interface{}{}
	if p.name != nil {
		body["name"] = *p.name
	}
	if p.prices.set {
		body["prices"] = p.prices.value
	}
	return body
